/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import page2020.core.App;import page2020.view.Content;import page2020.view.Tag;import page2020.view.Text;import page2020.view.bs4.B4button.BtnColor;import page2020.view.bs4.B4show.D;import page2020.view.html5.H5span;public class B4inputGroup extends B4boxes<B4inputGroup> {	public static final String group = "input-group";	public static final String sm = "input-group-sm";	public static final String lg = "input-group-lg";	public static final String prepend = "input-group-prepend";	public static final String append = "input-group-append";	public static final String groupText = "input-group-text";	public B4inputGroup() {			super();		super.data(PageKey.type, "inputGroup");		super.cssClass(group);	}	public B4inputGroup small() {		return super.boxes().cssClass(sm);	}	public B4inputGroup large() {		return super.boxes().cssClass(lg);	}	public B4inputGroup before() {		super.box(new B4element().cssClass(prepend));		return this;	}	public B4inputGroup after() {		super.box(new B4element().cssClass(append));		return this;	}	public B4inputGroup addon(String string) {		return super.append(new H5span().cssClass(groupText).text(string));	}	public B4inputGroup addon(Text text) {		return super.append(new H5span().cssClass(groupText).append(text));	}	public B4inputGroup addon(H5span span) {		return super.append(span.cssClass(groupText));	}	public B4inputGroup addon(Content<?> c) {		return super.append(new B4element().cssClass(groupText).append(c));	}	public B4inputGroup addon(String ctrlName, String[] addon) {		super.box("div", append);		for (String icon : addon) {			String color = null;			switch (icon) {			case Addon.search:				color = BtnColor.primary;				break;			case Addon.add:				color = BtnColor.success;				break;			case Addon.edit:				color = BtnColor.warning;				break;			case Addon.remove:				color = BtnColor.danger;				break;			case Addon.clear:				color = BtnColor.secondary;				break;			case Addon.yes:				color = BtnColor.primary;				break;			case Addon.no:				color = BtnColor.danger;				break;			default:				continue;			}			super.append(new B4button(color).name(ctrlName + "." + icon).append(App.icon("addon." + icon)));			super.append(new H5span().cssClass("tip", D.none).code("addon." + icon + ".tip"));		}		return this;	}	public B4inputGroup dropdown(B4dropdown dropdown) {		return super.append(dropdown.getContents());	}	public B4inputGroup control(Tag<?> control) {		return super.boxes().append((Content<?>) control.cssClass(B4ctrl.control));	}}